pragma solidity 0.8.36;
contract C { enum Mode { Off, On, Paused } function values() external pure returns (Mode, Mode, Mode, uint8, uint8, int8, int8) { return (Mode.On, type(Mode).min, type(Mode).max, type(uint8).min, type(uint8).max, type(int8).min, type(int8).max); } }
